import React, {useEffect, useMemo, useState} from "react";
import {InputLabel} from "@mui/material";
import {useNavigate, useParams} from "react-router-dom";
import {toast} from "react-toastify";
import {useForm} from "react-hook-form";
import {yupResolver} from "@hookform/resolvers/yup";
import CoreButton from "../../ui/buttons/coreButton";
import {getApiErrorMessage} from "../../api/errors";
import {FormSurface, MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup} from "../../ui/commonStyled/commonStyled";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import CoreTextField from "../../ui/textFields/coreTextField";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import QueryError from "../shared/QueryError";
import Loader from "../../ui/loader/loader";
import CoreFormHelperText from "../../ui/errors/CoreFormHelperText";
import {CategoryType} from "../../models/category";
import {useCreateServiceMutation, useEditServiceMutation, useGetServiceByIdQuery} from "./servicesApi";
import {serviceSchema} from "./serviceSchema";
import {useTranslation} from "../../i18n";
import ImageUploadField from "../../ui/fileUpload/ImageUploadField";
import CharacteristicEditor, {CharacteristicRow} from "../shared/characteristics/CharacteristicEditor";
import CustomFieldEditor, {
    CustomFieldRow,
    customFieldRowsToRecord,
    customFieldsToRows,
    getCustomFieldsValidationError,
} from "../shared/customFields/CustomFieldEditor";

interface FormInput {
    name: string;
    description: string;
    price: number;
    categoryId: string;
}

const CreateOrEditService = () => {
    const {id} = useParams<{id: string}>();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const validationSchema = useMemo(() => serviceSchema(t), [t]);
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState("");
    const [modifications, setModifications] = useState<CharacteristicRow[]>([]);
    const [modificationsError, setModificationsError] = useState("");
    const [fields, setFields] = useState<CustomFieldRow[]>([]);
    const [fieldsError, setFieldsError] = useState("");
    const {setValue, getValues, register, handleSubmit, formState: {errors}} = useForm<FormInput>({
        resolver: yupResolver(validationSchema),
        defaultValues: {description: "", price: 0},
    });

    const {data: serviceDetails, isLoading, isError, error, refetch} = useGetServiceByIdQuery(id!, {skip: !id});
    const {data: categories, isLoading: isCategoriesLoading, isError: isCategoriesError, error: categoriesError, refetch: refetchCategories} = useGetLastLevelCategoriesQuery({type: CategoryType.Service});

    useEffect(() => {
        if (!serviceDetails) return;
        setValue("categoryId", String(serviceDetails.categoryId));
        setValue("name", serviceDetails.name);
        setValue("description", serviceDetails.description ?? "");
        setValue("price", serviceDetails.price);
        setModifications(Object.entries(serviceDetails.modifications ?? {}).map(([name, value]) => ({name, value})));
        setFields(customFieldsToRows(serviceDetails.fields));
    }, [serviceDetails, setValue]);

    useEffect(() => {
        if (imageFile) {
            const previewUrl = URL.createObjectURL(imageFile);
            setImagePreview(previewUrl);
            return () => URL.revokeObjectURL(previewUrl);
        }
        setImagePreview(serviceDetails?.imageName ?? "");
    }, [imageFile, serviceDetails?.imageName]);

    const [createService, {isLoading: isCreatingService}] = useCreateServiceMutation();
    const [editService, {isLoading: isEditingService}] = useEditServiceMutation();
    const isSaving = isCreatingService || isEditingService;

    const validateModifications = () => {
        const names = new Set<string>();
        for (const modification of modifications) {
            const name = modification.name.trim();
            if (!name || !modification.value.trim()) {
                setModificationsError(t("Characteristic name and value are required."));
                return false;
            }
            const normalizedName = name.toLocaleLowerCase();
            if (names.has(normalizedName)) {
                setModificationsError(t("Characteristic names must be unique."));
                return false;
            }
            names.add(normalizedName);
        }
        setModificationsError("");
        return true;
    };

    const onSubmit = async () => {
        const customFieldsError = getCustomFieldsValidationError(fields, t);
        setFieldsError(customFieldsError);
        if (!validateModifications() || customFieldsError) return;
        const formData = new FormData();
        formData.append("categoryId", getValues("categoryId"));
        formData.append("name", getValues("name"));
        if (getValues("description")?.trim()) formData.append("description", getValues("description"));
        formData.append("price", getValues("price").toString());
        formData.append("modifications", JSON.stringify(Object.fromEntries(
            modifications.map(({name, value}) => [name.trim(), value.trim()]),
        )));
        formData.append("fields", JSON.stringify(customFieldRowsToRecord(fields)));
        if (imageFile) formData.append("imageFile", imageFile);

        try {
            if (id) {
                formData.append("id", id);
                await editService(formData).unwrap();
                toast.success(t("Service was changed"));
            } else {
                await createService(formData).unwrap();
                toast.success(t("Service was created"));
            }
            navigate("/servicesManagement", {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Service was not saved")));
        }
    };

    if (isCategoriesLoading || isLoading) return <Loader/>;
    if (id && (isError || !serviceDetails)) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;
    if (isCategoriesError) return <MainDiv><QueryError error={categoriesError} onRetry={refetchCategories}/></MainDiv>;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{id ? t("Edit service") : t("New service")}</PageTitle>
                    <PageSubtitle>{t("Service category, image, price, and arbitrary characteristics.")}</PageSubtitle>
                </PageTitleGroup>
            </PageHeader>
            <FormSurface onSubmit={handleSubmit(onSubmit)}>
                <CoreFormControl verticalMargin>
                    <InputLabel>{t("Category")}</InputLabel>
                    <CoreSelect defaultValue={serviceDetails?.categoryId ?? ""} value={getValues("categoryId")} disabled={Boolean(id)} register={register} name="categoryId" error={errors.categoryId?.message} label={t("Category")} menuItemProps={categories}/>
                </CoreFormControl>
                {errors.categoryId && <CoreFormHelperText errorMessage={errors.categoryId.message}/>}
                <CoreTextField label={t("Name")} register={register} name="name" error={errors.name?.message} verticalMargin/>
                <CoreTextField label={t("Description")} register={register} name="description" error={errors.description?.message} verticalMargin/>
                <CoreTextField type="number" inputProps={{min: 0, step: "any"}} label={t("Price")} register={register} name="price" error={errors.price?.message} verticalMargin/>
                <ImageUploadField label={t("Image")} actionText={t("Choose file")} emptyText={t("No file selected")} hint={t("PNG, JPG or WEBP")} fileName={imageFile?.name} previewSrc={imagePreview} previewAlt={getValues("name") || t("Service")} onChange={(event) => setImageFile(event.target.files?.[0] ?? null)}/>
                <CustomFieldEditor value={fields} onChange={setFields} error={fieldsError}/>
                <CharacteristicEditor title={t("Characteristics")} nameLabel={t("Characteristic name")} valueLabel={t("Value")} addLabel={t("Add characteristic")} removeLabel={t("Remove characteristic")} value={modifications} onChange={setModifications} error={modificationsError}/>
                <CoreButton verticalMargin type="submit" fullWidth muiType="success" disabled={isSaving} text={isSaving ? t("Saving...") : t("Save")}/>
                <CoreButton muiType="secondary" disabled={isSaving} text={t("Cancel")} onClick={() => navigate(id ? `/servicesManagement/${id}` : "/servicesManagement")}/>
            </FormSurface>
        </MainDiv>
    );
};

export default CreateOrEditService;
