import * as yup from "yup";
import {Translate} from "../../i18n";

export const serviceSchema = (t: Translate) => yup.object().shape({
    name: yup.string().required(t("Please fill in this field!")),
    description: yup.string().ensure(),
    price: yup.number()
        .min(0, t("Цена не может быть отрицательной."))
        .typeError(t("Please fill in this field!"))
        .required(),
    categoryId: yup.string().required(t("Please fill in this field!")),
});
